	private static LmdbInMemoryAdjacencyIndex build(List<Quad> quads, LmdbAdjacencyCoverage coverage,
			LmdbAdjacencyMemoryAccount account) throws IOException {
		return LmdbAdjacencyBaseBuilder.build(new SyntheticScanner(quads), coverage, account, BASE_REGION,
				WORKSPACE_REGION);
	}

	/**
	 * Differential oracle: every quad's outgoing and incoming rows decode to exactly the source pair sets.
	 */
	private static void verifyIndexMatchesQuads(LmdbInMemoryAdjacencyIndex index, List<Quad> quads) {
		// group source of truth
		TreeMap<String, TreeSet<long[]>> expected = new TreeMap<>();
		for (Quad quad : quads) {
			int outPlane = quad.explicit ? LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT
					: LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED;
			int inPlane = quad.explicit ? LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT
					: LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED;
			expected.computeIfAbsent(quad.s + "/" + outPlane + "/" + quad.p,
					k -> new TreeSet<>(SyntheticScanner.pairComparator())).add(new long[] { quad.o, quad.c });
			expected.computeIfAbsent(quad.o + "/" + inPlane + "/" + quad.p,
					k -> new TreeSet<>(SyntheticScanner.pairComparator())).add(new long[] { quad.s, quad.c });
		}
		for (var entry : expected.entrySet()) {
			String[] parts = entry.getKey().split("/");
			long key = Long.parseLong(parts[0]);
			int plane = Integer.parseInt(parts[1]);
			long predicate = Long.parseLong(parts[2]);
			long handle = index.findRun(key, plane, predicate);
			assertThat(handle).as("row %s must be present", entry.getKey()).isPositive();
			long edgeCount = LmdbAdjacencyRunCodec.edgeCount(index.arenaCatalog(), handle);
			assertThat(edgeCount).as("row %s degree", entry.getKey()).isEqualTo(entry.getValue().size());
			int i = 0;
			for (long[] pair : entry.getValue()) {
				assertThat(LmdbAdjacencyRunCodec.neighborAt(index.arenaCatalog(), handle, i))
						.as("row %s neighbor %d", entry.getKey(), i)
						.isEqualTo(pair[0]);
				assertThat(LmdbAdjacencyRunCodec.contextAt(index.arenaCatalog(), index.contextCatalog(), handle, i))
						.as("row %s context %d", entry.getKey(), i)
						.isEqualTo(pair[1]);
				i++;
			}
		}
	}

	@Test
	void explicitDefaultGraphBuildsBothDirections() throws IOException {
		List<Quad> quads = List.of(
				new Quad(uri(1), uri(100), uri(2), 0, true),
				new Quad(uri(1), uri(100), uri(3), 0, true),
				new Quad(uri(2), uri(100), uri(3), 0, true),
				new Quad(uri(1), uri(101), uri(2), 0, true));
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1 << 30);
		try (LmdbInMemoryAdjacencyIndex index = build(quads, LmdbAdjacencyCoverage.full(), account)) {
			assertThat(index.statementCount()).isEqualTo(4);
			assertThat(index.incidenceCount()).isEqualTo(8);
			verifyIndexMatchesQuads(index, quads);

			// exact-empty proofs under FULL coverage
			assertThat(index.findRun(uri(1), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, uri(999)))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND); // predicate absent at the base
			assertThat(index.findRun(uri(42), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, uri(100)))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND); // node absent
			assertThat(index.findRun(uri(3), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, uri(100)))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND); // node present only as an object
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

