	@Test
	void referenceLiteralAndInlinedLiteralObjects() throws IOException {
		long inlined = inlineInt(42);
		long referenceLiteral = literal(77);
		List<Quad> quads = List.of(
				new Quad(uri(1), uri(100), inlined, 0, true),
				new Quad(uri(1), uri(100), referenceLiteral, 0, true),
				new Quad(uri(2), uri(100), inlined, 0, true));
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1 << 30);
		try (LmdbInMemoryAdjacencyIndex index = build(quads, LmdbAdjacencyCoverage.full(), account)) {
			verifyIndexMatchesQuads(index, quads);
			// the inlined object's incoming row is served by the inline index
			long handle = index.findRun(inlined, LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, uri(100));
			assertThat(handle).isPositive();
			assertThat(LmdbAdjacencyRunCodec.edgeCount(index.arenaCatalog(), handle)).isEqualTo(2);
			// a missing inline key in a covered plane is exact-empty
			assertThat(index.findRun(inlineInt(43), LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, uri(100)))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND);
			// an inlined key can never have outgoing rows
			assertThat(index.findRun(inlined, LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, uri(100)))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND);
		}
	}

