	@Test
	void selectedCoverageBuildsAllFourPlanesForConfiguredPredicatesOnly() throws IOException {
		long selected = uri(100);
		long unselected = uri(200);
		List<Quad> quads = List.of(
				new Quad(uri(1), selected, uri(2), 0, true),
				new Quad(uri(1), selected, uri(3), 0, false),
				new Quad(uri(1), unselected, uri(2), 0, true),
				new Quad(uri(4), unselected, inlineInt(7), 0, true));
		LmdbAdjacencyCoverage coverage = LmdbAdjacencyCoverage.selected(new long[] { selected }, Set.of());
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1 << 30);

		try (LmdbInMemoryAdjacencyIndex index = build(quads, coverage, account)) {
			// selected predicate: all four planes served
			assertThat(index.findRun(uri(1), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, selected))
					.isPositive();
			assertThat(index.findRun(uri(1), LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED, selected))
					.isPositive();
			assertThat(index.findRun(uri(2), LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, selected))
					.isPositive();
			assertThat(index.findRun(uri(3), LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED, selected))
					.isPositive();
			// unselected predicate is NOT_COVERED, never NOT_FOUND
			assertThat(index.findRun(uri(1), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, unselected))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_COVERED);
			assertThat(index.findRun(inlineInt(7), LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, unselected))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_COVERED);
			// a covered-but-empty selected row is exact-empty
			assertThat(index.findRun(uri(9), LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, selected))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND);
		}
	}

	@Test
	void closingTheIndexReleasesEveryCharge() throws IOException {
		List<Quad> quads = List.of(new Quad(uri(1), uri(100), uri(2), 0, true));
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1 << 30);
		LmdbInMemoryAdjacencyIndex index = build(quads, LmdbAdjacencyCoverage.full(), account);

		assertThat(account.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.BASE)).isPositive();
		assertThat(account.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.BUILD_COUNTERS)).isZero();
		index.close();
		assertThat(account.totalChargedBytes()).isZero();
	}
